pse25" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse25" data-bs-toggle="collapse" type="button">Internationalization</button></h2><div aria-labelledby="flush-heading25" class="accordion-collapse collapse show" id="flush-collapse25"><div class="accordion-body"><ul><li class="leftmenu"><a href="/internationalization">Internationalization</a></li><li class="leftmenu"><a href="/ResourceBundle-class">ResourceBundle class</a></li><li class="leftmenu"><a href="/internationalizing-date">I18N with Date</a></li><li class="leftmenu"><a href="/internationalizing-time">I18N with Time</a></li><li class="leftmenu"><a href="/internationalizing-number">I18N with Number</a></li><li class="leftmenu"><a href="/internationalizing-currency">I18N with Currency</a></li></ul></div></div></div><div class="accordion-item" style="background-color:var(--sidebar)"><h2 class="accordion-header" id="flush-heading26"><button aria-controls="flush-collapse26" aria-expanded="true" class="accordion-button sidebar-btn" data-bs-target="#flush-collapse26" data-bs-toggle="collapse" type="button">Java Projects</button></h2><div aria-labelledby="flush-heading26" class="accordion-collapse collapse show" id="flush-collapse26"><div class="accordion-body"><ul><li class="leftmenu"><a href="/free-java-projects">Free Java Projects</a></li><li class="leftmenu"><a href="/payment-billing-product-project">Payment Bill(JSP)</a></li><li class="leftmenu"><a href="/transport-company-project">Transport (JSP)</a></li><li class="leftmenu"><a href="/connect-globe-project">Connect Globe (JSP)</a></li><li class="leftmenu"><a href="/online-banking-project">Online Banking (JSP)</a></li><li class="leftmenu"><a href="/online-quiz-project">Online Quiz (JSP)</a></li><li class="leftmenu"><a href="/city-classified-and-search-project">Classified (JSP)</a></li><li class="leftmenu"><a href="/mailcasting-project">Mailcasting (JSP)</a></li><li class="leftmenu"><a href="/online-library-project">Online Library (JSP)</a></li><li class="leftmenu"><a href="/pharmacy-project">Pharmacy (JSP)</a></li><li class="leftmenu"><a href="/company-mailer-servlet-project">Mailer (Servlet)</a></li><li class="leftmenu"><a href="/baby-care-project-in-servlet">Baby Care (Servlet)</a></li><li class="leftmenu"><a href="/broadcasting-chat-server-project">Chat Server (Core)</a></li><li class="leftmenu"><a href="/library-management-system-in-java-swing">Library (Core)</a></li><li class="leftmenu"><a href="/online-exam-project-in-java-swing-without-database">Exam System (Core)</a></li><li class="leftmenu"><a href="/java-application-world-project">Java Apps (Core)</a></li><li class="leftmenu"><a href="/fee-report-project-in-java">Fee Report (Core)</a></li><li class="leftmenu"><a href="/fee-management-project-in-servlet">Fee (Servlet)</a></li><li class="leftmenu"><a href="/elibrary-project-in-servlet">eLibrary (Servlet)</a></li><li class="leftmenu"><a href="/embedded-system-project-fire-detection-and-control-system">Fire Detection</a></li><li class="leftmenu"><a href="/embedded-system-project-rfid-based-attendance-system">Attendance System</a></li><li class="leftmenu"><a href="/java-mcq">Java MCQ</a></li></ul></div></div></div></div></div></div><div class="col-12 col-md-7"><div class="overview"><div id="city"><table><tbody><tr><td><div id="bottomnextup"><a class="next" href="java-arraylist">next →</a> <a class="next" href="awt-components-in-java">← prev</a></div><div class="custom-nav-wrapper"><div class="custom-nav-tab"><a class="custom-nav-node" href="java-tutorial" title="Java Tutorials"><svg fill="currentColor" height="1em" stroke="currentColor" stroke-width="0" viewbox="0 0 512 512" width="1em" xmlns="http://www.w3.org/2000/svg"><path d="M416 221.25V416a48 48 0 0 1-48 48H144a48 48 0 0 1-48-48V96a48 48 0 0 1 48-48h98.75a32 32 0 0 1 22.62 9.37l141.26 141.26a32 32 0 0 1 9.37 22.62z" fill="none" stroke-linejoin="round" stroke-width="32"></path><path d="M256 56v120a32 32 0 0 0 32 32h120m-2